-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

create table public.study_days (
  user_id uuid not null,
  day date not null,
  deck_id text not null,
  answers integer default 0 not null,
  practice integer default 0 not null,
  new_seen integer default 0 not null,
  failed integer default 0 not null,
  ms bigint default 0 not null,
  constraint study_days_pkey PRIMARY KEY (user_id, day, deck_id),
  constraint study_days_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE,
  constraint study_days_answers_check CHECK ((answers >= 0)),
  constraint study_days_deck_id_check CHECK ((deck_id ~ '^[0-9]{1,20}$'::text)),
  constraint study_days_failed_check CHECK ((failed >= 0)),
  constraint study_days_ms_check CHECK ((ms >= 0)),
  constraint study_days_new_seen_check CHECK ((new_seen >= 0)),
  constraint study_days_practice_check CHECK ((practice >= 0))
);

CREATE INDEX study_days_day ON public.study_days USING btree (day);

alter table public.study_days enable row level security;

create policy "read own days" on public.study_days
  as permissive
  for select
  to authenticated
  using (((user_id = ( SELECT auth.uid() AS uid)) AND ( SELECT public.is_allowed_user() AS is_allowed_user)));

grant select on table public.study_days to authenticated;
grant delete, insert, maintain, references, select, trigger, truncate, update on table public.study_days to service_role;
